// The CLI prints one JSON line with --json. Take the last JSON line of stdout.
const out = String($json.stdout || '').trim().split('\n').filter(Boolean);
let summary = null;
for (let i = out.length - 1; i >= 0; i--) {
  try { summary = JSON.parse(out[i]); break; } catch (e) { /* not JSON */ }
}
if (!summary) {
  return [{ json: { pass: false, score: null, reasons: ['The audit did not produce a result: ' + String($json.stderr || 'no output').slice(0, 300)] } }];
}
return [{ json: summary }];

